---@class RegressionBindCodeNode
local RegressionBindCodeNode = Class('RegressionBindCodeNode')
local KTool = CS.Engine.Lib.KTool

---@field BtnClose                      	UnityEngine.UI.Button
---@field FontStyleButton               	Game.Native.Common.FontStyleButton
---@field InputField                    	UnityEngine.UI.InputField

function RegressionBindCodeNode:__init()
    
end

function RegressionBindCodeNode:__delete()
    
end

function RegressionBindCodeNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickBtnCodeBtnHandler_))
    SetButtonAction(self.BtnClose, Bind(self, self.OnClickCloseBtnHandler_))
end

function RegressionBindCodeNode:Start()
end

function RegressionBindCodeNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function RegressionBindCodeNode:SetBindCB(handler)
    self.bindCB_ = handler
end
function RegressionBindCodeNode:GetBindCB()
    return self.bindCB_
end

function RegressionBindCodeNode:SetActivityType(type, id)
    self.activityType_ = checkInt(type)
    self.activityId_   = checkInt(id)
end
function RegressionBindCodeNode:GetActivityType()
    return checkInt(self.activityType_)
end

function RegressionBindCodeNode:GetActivityId()
    return checkInt(self.activityId_)
end

function RegressionBindCodeNode:SetBindCode(code)
    local isHasCode = code ~= nil and type(code) == "string" and  string.trim(code) ~= ""
    if isHasCode then
        self.InputField.text = code
        self.bindCode_ = code
    end
    self:RefreshBtnStatue(isHasCode)
end
function RegressionBindCodeNode:GetBindCode()
    return self.bindCode_
end

function RegressionBindCodeNode:RefreshBtnStatue(isBind)
    self.InputField.enabled = not isBind

    if isBind then
        self.FontStyleButton:ResetFontStyle("B7", localize("已绑定"))
    else
        self.FontStyleButton:ResetFontStyle("B6", localize("绑定"))
    end
end

function RegressionBindCodeNode:OnClickBtnCodeBtnHandler_()
    if self:GetBindCode() ~= nil then return end

    local code = string.trim(self.InputField.text)
    if string.len(code) < 6 then
        GameUtils.Toast(localize("请输入有效的召回码"))
        return
    end

    GameUtils.Request(Interfaces.RegressTaskBindCode, {activityUuid = self:GetActivityId(), code = code, type = self:GetActivityType()}, function(request, response)
        if response.errCode == 0 then
            -- refresh
            self:SetBindCode(code)

            if self:GetBindCB() then
                self:GetBindCB()(code)
            end

            GameUtils.Toast(localize("绑定成功"))
        end
    end)
end

function RegressionBindCodeNode:OnClickCloseBtnHandler_()
    KTool.SafeDelete(self.controller.gameObject)
end

return RegressionBindCodeNode
 
 